beforeFiles.src/shared/chunks.mjs:
export function chunks(values, size) {
  if (!Number.isInteger(size) || size < 1) throw new RangeError("size must be positive");
  return Array.from({length: Math.ceil(values.length / size)}, (_, index) => values.slice(index * size, (index + 1) * size));
}

beforeFiles.src/workers/recovery.mjs:
// Consumes the same queue policy used by the lease allocator. All timestamps are milliseconds.
export function mayRecover(record, policy, now) {
  const expiry = record.acquiredAt + policy.leaseDuration;
  return now >= expiry;
}

beforeFiles.src/tools/replay.mjs:
// Replay one item per logical queue job, using the allocator's idempotency semantics.
export function distinctReplayJobs(jobs) {
  return [...new Map(jobs.map((job) => [job.idempotencyKey, job])).values()];
}

