import { jobKey } from '../src/queue/identity.mjs';
import { distinctReplayJobs } from '../src/tools/replay.mjs';
const jobs = [{queueId:'invoices',idempotencyKey:'sample'}, {queueId:'mail',idempotencyKey:'sample'}];
assert.equal(distinctReplayJobs(jobs).length, new Set(jobs.map(jobKey)).size);

