beforeFiles.src/import/übersicht.mjs:
// Catalog imports retain one product for each catalog name, using the catalog's identity policy.
export function distinctProducts(products) {
  const byName = new Map(
    products.map((product) => [product.name.toLowerCase(), product]),
  );
  return [...byName.values()];
}

